import ctypes as c, subprocess, time
from pywinauto import Desktop
from ctypes import wintypes as w

user32=c.windll.user32
try:
    user32.GetDpiForSystem.restype=w.UINT
    print("SYSTEM_DPI",user32.GetDpiForSystem(),flush=True)
except Exception as e:
    print("SYSTEM_DPI_ERROR",repr(e),flush=True)

subprocess.Popen(["cmd","/c","start","", "ms-settings:display"],shell=False)
win=None
end=time.monotonic()+20
while time.monotonic()<end:
    for x in Desktop(backend="uia").windows(control_type="Window"):
        try:
            name=(x.window_text() or "").lower()
            if "settings" in name or "설정" in name:
                win=x
                break
        except Exception:
            pass
    if win: break
    time.sleep(.4)
if not win:
    raise RuntimeError("Settings display window not found")
time.sleep(2)
print("SETTINGS_TITLE",repr(win.window_text()),flush=True)
controls=[]
for x in win.descendants():
    try:
        info=x.element_info
        name=info.name or ""
        aid=info.automation_id or ""
        ctype=info.control_type or ""
        if any(k in name.lower() for k in ("scale","배율","크기","layout","레이아웃")) or ctype in ("ComboBox","Slider"):
            controls.append((ctype,name,aid,x.is_enabled(),x.is_visible()))
    except Exception:
        pass
print("MATCH_COUNT",len(controls),flush=True)
for row in controls[:120]:
    print("CTRL",repr(row),flush=True)
try: win.close()
except Exception: pass

